 3→/**
 4→ * Converts a string to a URL-safe slug.
 5→ * e.g. "My Quiz Title!" -> "my-quiz-title"
 6→ */
 7→export function slugify(text: string): string {
 8→  return text
 9→    .toLowerCase()
10→    .replace(/[^a-z0-9\s-]/g, "")
11→    .replace(/\s+/g, "-")
12→    .replace(/-+/g, "-")
13→    .replace(/^-|-$/g, "");
14→}
15→
16→/**
17→ * Generates a slug that is unique per shop.
18→ * Appends a counter suffix if the base slug is already taken.
19→ */
20→export async function generateUniqueSlug(shop: string, title: string): Promise<string> {
21→  const base = slugify(title) || "quiz";
22→  let slug = base;
23→  let counter = 0;
24→  while (await db.quiz.findFirst({ where: { shop, slug } })) {
25→    counter++;
26→    slug = `${base}-${counter}`;
27→  }
28→  return slug;
29→}
30→
31→/**
32→ * Safely parses a JSON string, returning `fallback` on any parse error.
33→ * Use this for all Prisma JSON string fields (Law 6).
34→ */
35→export function parseSafe<T>(str: string, fallback: T): T {
36→  try {
37→    return JSON.parse(str) as T;
38→  } catch {
39→    return fallback;
40→  }
41→}
42→
43→/**
44→ * Formats a number as USD currency.
45→ * e.g. 29.99 -> "$29.99"
46→ */
47→export function formatCurrency(amount: number): string {
48→  return new Intl.NumberFormat("en-US", {
49→    style:    "currency",
50→    currency: "USD",
51→  }).format(amount);
52→}
53→
54→/**
55→ * Formats a Date or ISO string as a human-readable date.
56→ * e.g. "2024-03-25T00:00:00Z" -> "Mar 25, 2024"
57→ */
58→export function formatDate(date: Date | string): string {
59→  return new Intl.DateTimeFormat("en-US", {
60→    month: "short",
61→    day:   "numeric",
62→    year:  "numeric",
63→  }).format(new Date(date));
64→}
65→
66→/**
67→ * Truncates a string to `maxLength` characters, appending "…" if truncated.
68→ */
69→export function truncate(text: string, maxLength: number): string {
70→  if (text.length <= maxLength) return text;
71→  return `${text.slice(0, maxLength - 1)}…`;
72→}
73→
74→/**
75→ * Returns true if the value is a non-null object (not an array).
76→ */
77→export function isPlainObject(value: unknown): value is Record<string, unknown> {
78→  return typeof value === "object" && value !== null && !Array.isArray(value);
79→}
