// ─── Helper: derive questionTypes display string ──────────────────────────────

function deriveQuestionTypes(questions: QuestionDefinition[]): string {
  const unique = Array.from(new Set(questions.map((q) => q.type)));
  return unique
    .map((t) =>
      t
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" "),
    )
    .join(", ");
}

// ─── Exported Functions ───────────────────────────────────────────────────────

/**
 * Returns lightweight metadata for every template, suitable for the template
 * picker UI. No DB access needed — all data is in-memory.
 */
export function getTemplatesMeta(): TemplateMeta[] {
  return TEMPLATES.map((t) => ({
    id: t.id,
    name: t.name,
    category: t.category,
    questionCount: t.questions.length,
    questionTypes: deriveQuestionTypes(t.questions),
    badge: t.badge,
  }));
}

/**
 * Creates a full quiz (quiz + questions + answers + result page) from one of
 * the built-in template definitions. All writes are wrapped in a single
 * $transaction for atomicity.
 *
 * Returns the newly created quiz ID.
 */
export async function createQuizFromTemplate(
  shop: string,
  templateId: string,
): Promise<string> {
  const template = TEMPLATES.find((t) => t.id === templateId);
  if (!template) {
    throw new Error(`Template "${templateId}" not found`);
  }

  const slug = await generateUniqueSlug(shop, template.quizTitle);

  const quiz = await db.$transaction(async (tx) => {
    // 1. Create the quiz record
    const newQuiz = await tx.quiz.create({
      data: {
        shop,
        title: template.quizTitle,
        description: template.quizDescription,
        slug,
        status: "draft",
        type: template.quizType,
        settings: JSON.stringify({}),
        styling: JSON.stringify({}),
      },
    });

    // 2. Create questions and their answers
    for (const qDef of template.questions) {
      const question = await tx.question.create({
        data: {
          quizId: newQuiz.id,
          type: qDef.type,
          title: qDef.title,
          description: qDef.description ?? null,
          required: qDef.required,
          position: qDef.position,
          settings: JSON.stringify(qDef.settings),
          logic: JSON.stringify({}),
        },
      });

      for (let i = 0; i < qDef.answers.length; i++) {
        const aDef = qDef.answers[i];
        await tx.answer.create({
          data: {
            questionId: question.id,
            text: aDef.text,
            position: i,
            score: (i + 1) * 10,
            productTags: JSON.stringify(aDef.tags),
            metadata: JSON.stringify({}),
          },
        });
      }
    }

    // 3. Create the default result page
    await tx.resultPage.create({
      data: {
        quizId: newQuiz.id,
        title: "Your Personalized Recommendations",
        description: "Based on your answers, here are our top picks for you!",
        type: "default",
        matchTags: JSON.stringify([]),
        productLimit: 4,
        layout: "grid",
        showDiscount: false,
        styling: JSON.stringify({}),
        position: 0,
      },
    });

    return newQuiz;
  });

  return quiz.id;
}

/**
 * Creates a blank quiz with one placeholder multiple-choice question and a
 * default result page. Intended for merchants who prefer to build from scratch.
 *
 * Returns the newly created quiz ID.
 */
export async function createBlankQuiz(shop: string): Promise<string> {
  const slug = await generateUniqueSlug(shop, "My Quiz");

  const quiz = await db.$transaction(async (tx) => {
    // 1. Create the quiz record
