        type: "multiple-choice",
        title: "Your first question",
        required: true,
        position: 0,
        settings: JSON.stringify({}),
        logic: JSON.stringify({}),
      },
    });

    // 3. Create the two placeholder answers
    await tx.answer.create({
      data: {
        questionId: question.id,
        text: "Option A",
        position: 0,
        score: 10,
        productTags: JSON.stringify([]),
        metadata: JSON.stringify({}),
      },
    });
    await tx.answer.create({
      data: {
        questionId: question.id,
        text: "Option B",
        position: 1,
        score: 20,
        productTags: JSON.stringify([]),
        metadata: JSON.stringify({}),
      },
    });

    // 4. Create the default result page
    await tx.resultPage.create({
      data: {
